--YHAAO-17341 start
UPDATE nurse_site_maintain_item SET is_finish = (CASE WHEN view_mount.no_check_count > 0 THEN FALSE ELSE TRUE END) FROM (SELECT nsmd.parent_id,count(nsmd.id)-count(nsmd.check_value) AS no_check_count FROM nurse_site_maintain_item nsmi,nurse_site_maintain_data nsmd WHERE nsmi.id = nsmd.parent_id GROUP BY nsmd.parent_id) AS view_mount WHERE id = view_mount.parent_id;
UPDATE nurse_site_maintain SET is_finish = (CASE WHEN view_mount.no_check_count > 0 THEN FALSE ELSE TRUE END) FROM (SELECT item2.parent_id,count(item2.parent_id) - SUM(item2.checked_count) AS no_check_count FROM (SELECT item1.parent_id,(CASE WHEN item1.is_finish = TRUE THEN 1 ELSE 0 END) AS checked_count  FROM nurse_site_maintain_item item1)AS item2 GROUP BY item2.parent_id) AS view_mount WHERE id = view_mount.parent_id;
UPDATE nurse_site_maintain_item_history SET is_finish = (CASE WHEN view_mount.no_check_count > 0 THEN FALSE ELSE TRUE END) FROM (SELECT nsmd.parent_id,count(nsmd.id)-count(nsmd.check_value) AS no_check_count FROM nurse_site_maintain_item_history nsmi,nurse_site_maintain_data_history nsmd WHERE nsmi.id = nsmd.parent_id GROUP BY nsmd.parent_id) AS view_mount WHERE id = view_mount.parent_id;
UPDATE nurse_site_maintain_history SET is_finish = (CASE WHEN view_mount.no_check_count > 0 THEN FALSE ELSE TRUE END) FROM (SELECT item2.parent_id,count(item2.parent_id) - SUM(item2.checked_count) AS no_check_count FROM (SELECT item1.parent_id,(CASE WHEN item1.is_finish = TRUE THEN 1 ELSE 0 END) AS checked_count  FROM nurse_site_maintain_item_history item1)AS item2 GROUP BY item2.parent_id) AS view_mount WHERE id = view_mount.parent_id;
CREATE INDEX nurse_site_maintain_is_finish ON nurse_site_maintain (is_finish);
CREATE INDEX nurse_site_maintain_history_is_finish ON nurse_site_maintain_history (is_finish);
CREATE INDEX nurse_site_maintain_item_is_finish ON nurse_site_maintain_item (is_finish);
CREATE INDEX nurse_site_maintain_item_history_is_finish ON nurse_site_maintain_item_history (is_finish);
